function normalizedState(raw){
 const record=v=>!!v&&typeof v==='object'&&!Array.isArray(v),num=(v,fallback,min=0,max=Number.MAX_SAFE_INTEGER)=>Number.isFinite(Number(v))?Math.max(min,Math.min(max,Number(v))):fallback;
 const out=blank();if(record(raw))for(const [k,v]of Object.entries(raw))if(!['__proto__','prototype','constructor'].includes(k))out[k]=v;
 out.profile=Object.assign(blank().profile,record(out.profile)?out.profile:{});
 out.profile.dailyMinutes=num(out.profile.dailyMinutes,60,15,240);out.profile.dailyQuestions=Math.round(num(out.profile.dailyQuestions,10,1,60));out.profile.speechRate=num(out.profile.speechRate,1,.5,2);
 for(const k of ['targetDate','elective','voiceURI','customReadings'])out.profile[k]=typeof out.profile[k]==='string'?out.profile[k]:blank().profile[k];
 out.profile.customReadings=out.profile.customReadings.slice(0,12000);if(out.profile.targetDate&&(!/^\d{4}-\d{2}-\d{2}$/.test(out.profile.targetDate)||!Number.isFinite(Date.parse(out.profile.targetDate+'T00:00:00'))))out.profile.targetDate='';
 const answer=a=>record(a)&&typeof a.id==='string'&&typeof a.correct==='boolean'&&Number.isInteger(a.choice)&&a.choice>=0&&a.choice<5&&Number.isFinite(a.at);
 out.history=Array.isArray(out.history)?out.history.filter(answer):[];
 for(const k of ['bookmarks','essentials'])out[k]=Array.isArray(out[k])?[...new Set(out[k].filter(v=>typeof v==='string'))]:[];
 for(const k of ['notes','mastery','essayDrafts','oral','time'])if(!record(out[k]))out[k]={};
 out.notes=Object.fromEntries(Object.entries(out.notes).filter(([,v])=>typeof v==='string'));
 out.time=Object.fromEntries(Object.entries(out.time).filter(([k,v])=>/^\d{4}-\d{2}-\d{2}$/.test(k)&&Number.isFinite(v)&&v>=0));
 out.mastery=Object.fromEntries(Object.entries(out.mastery).filter(([,m])=>record(m)&&typeof m.lastCorrect==='boolean'&&Number.isFinite(m.dueAt)&&Number.isFinite(m.lastAnsweredAt)).map(([id,m])=>[id,{...m,streak:num(m.streak,0),interval:num(m.interval,0),wrongCount:num(m.wrongCount,0)}]));
 out.essayDrafts=Object.fromEntries(Object.entries(out.essayDrafts).filter(([,d])=>record(d)).map(([id,d])=>[id,{text:typeof d.text==='string'?d.text:'',checked:Array.isArray(d.checked)?[...new Set(d.checked.filter(i=>Number.isInteger(i)&&i>=0))]:[],updatedAt:Number.isFinite(d.updatedAt)?d.updatedAt:null,remaining:d.remaining===null||d.remaining===undefined?null:num(d.remaining,null,0,86400)}]));
 out.oral=Object.fromEntries(Object.entries(out.oral).filter(([,d])=>record(d)).map(([id,d])=>[id,{note:typeof d.note==='string'?d.note:'',rating:['again','good'].includes(d.rating)?d.rating:null,at:Number.isFinite(d.at)?d.at:null}]));
 const ses=out.session,known=new Set((window.EXAM_QUESTIONS||[]).map(q=>q.id));
 if(!record(ses)||!Array.isArray(ses.ids)||!ses.ids.length||!ses.ids.every(id=>known.has(id)))out.session=null;
 else{ses.ids=[...new Set(ses.ids)];ses.index=Math.round(num(ses.index,0,0,ses.ids.length-1));ses.answers=record(ses.answers)?Object.fromEntries(Object.entries(ses.answers).filter(([id,a])=>ses.ids.includes(id)&&answer(a)&&a.id===id)):{};ses.selection=Number.isInteger(ses.selection)&&ses.selection>=0&&ses.selection<5?ses.selection:null;ses.startedAt=num(ses.startedAt,Date.now());ses.deadline=Number.isFinite(ses.deadline)&&ses.deadline>0?ses.deadline:null;ses.finished=ses.finished===true;ses.mode=['learn','review','bundle'].includes(ses.mode)?ses.mode:'learn';}
 return out;
}
let state;try{state=normalizedState(JSON.parse(localStorage.getItem(KEY)||'{}'));}catch{state=blank()}
