function sourceLink(label,url){return `<a class="source-link" href="${esc(url)}" target="_blank" rel="noopener noreferrer">${icon('link','small-icon')}${esc(label)}</a>`}
const ROOT_LAWS={patent:'334AC0000000121',utility:'334AC0000000123',design:'334AC0000000125',trademark:'334AC0000000127',copyright:'345AC0000000048',unfair:'405AC0000000047'};
function questionLawRoute(q){
 try{
  const url=new URL(q.sourceUrl);if(url.hostname!=='laws.e-gov.go.jp')return '';
  const lawId=url.pathname.match(/^\/law\/(\d{3}AC\d{10})(?:[\/_]|$)/)?.[1]||url.searchParams.get('lawid')?.split('_')[0];
  if(!Object.values(ROOT_LAWS).includes(lawId))return '';
  const label=String(q.sourceLabel||'').replace(/[０-９]/g,c=>String.fromCharCode(c.charCodeAt(0)-65248));
  const match=label.match(/(?:第)?(\d+)条((?:の\d+)*)/);if(!match)return '';
  return 'laws/'+lawId+'/'+String(Number(match[1]))+match[2].replace(/の(\d+)/g,(_,n)=>'_'+Number(n));
 }catch{return ''}
}
function questionLawLink(q){const next=questionLawRoute(q);return next?`<button class="text-button" style="margin-left:12px" data-nav="${next}">${icon('book','small-icon')}根拠条文を開く</button>`:''}
