function weekChart(){const dates=Array.from({length:7},(_,i)=>{const d=new Date();d.setDate(d.getDate()-6+i);return d}),mins=dates.map(d=>Math.floor((state.time[dayKey(d)]||0)/60)),max=Math.max(30,...mins);return `<div class="week-chart">${dates.map((d,i)=>`<div class="day-col ${i===6?'today':''}" title="${d.getMonth()+1}/${d.getDate()} ${mins[i]}分"><span>${mins[i]||''}</span><div class="bar" style="height:${Math.max(5,mins[i]/max*76)}px"></div><span>${['日','月','火','水','木','金','土'][d.getDay()]}</span></div>`).join('')}</div><div class="calendar-caption">直近7日間の学習時間（分）</div>`}
